SELECT order_id, unit_price_bucket, total_quantity, max_unit_price FROM (SELECT order_id, CASE WHEN unit_price >= 310 THEN 'high' WHEN unit_price >= 180 THEN 'mid' ELSE 'low' END AS unit_price_bucket, SUM(quantity) AS total_quantity, MAX(unit_price) AS max_unit_price FROM order_items WHERE unit_price >= 360 GROUP BY order_id, CASE WHEN unit_price >= 310 THEN 'high' WHEN unit_price >= 180 THEN 'mid' ELSE 'low' END) AS t WHERE total_quantity < 21;
